<script setup lang="ts">
import { onUnmounted, ref, watch } from 'vue';
import { ElMessageBox } from 'element-plus';
import type { components } from '@ism/api-client';
import { useSessionStore } from '../stores/session';
const props=defineProps<{application:components['schemas']['AdmissionApplication']}>();const emit=defineEmits<{changed:[]}>();
const canManage=ref(false),canDownload=ref(false);
const session=useSessionStore(),rows=ref<components['schemas']['AdmissionMaterialRequest'][]>([]),busy=ref(false),error=ref(''),instruction=ref(''),types=ref<string[]>([]),opened=ref(false);
const names={OPEN:'待供应商提交',SUBMITTED:'材料已提交，待采纳',ACCEPTED:'已采纳',CANCELLED:'索取已撤销'};let generation=0,disposed=false;const abort=new AbortController();
onUnmounted(()=>{disposed=true;generation++;abort.abort();});
async function load(){if(disposed)return;const current=++generation;busy.value=true;error.value='';try{const result=await session.client.GET('/admissions/{id}/material-requests',{params:{path:{id:props.application.id}},signal:abort.signal});if(disposed||current!==generation)return;if(!result.data)throw new Error(result.error?.error.message??'材料索取读取失败');rows.value=result.data.data.items;canManage.value=result.data.data.canManage;canDownload.value=result.data.data.canDownload;opened.value=true;}catch(e){if(current===generation)error.value=e instanceof Error?e.message:'读取失败';}finally{if(current===generation)busy.value=false;}}
watch(()=>[props.application.id,props.application.version],()=>{rows.value=[];opened.value=false;instruction.value='';types.value=[];void load();},{immediate:true});
async function publish(){if(busy.value)return;if(!instruction.value.trim()||!types.value.length||types.value.length>5){error.value='请选择1至5项材料，并填写供应商可见说明。';return;}try{await ElMessageBox.confirm('所选材料名称和说明将对供应商公开；内部文件、备注和审核意见不会公开。确认发布？','发布材料索取',{type:'warning'});}catch{return;}if(disposed)return;busy.value=true;error.value='';try{const result=await session.client.POST('/admissions/{id}/material-requests',{params:{path:{id:props.application.id}},body:{version:props.application.version,instruction:instruction.value.trim(),types:types.value},signal:abort.signal});if(!result.data)throw new Error(result.error?.error.message??'发布未成功，请刷新核查');instruction.value='';types.value=[];}catch(e){error.value=(e instanceof Error?e.message:'发布结果未知')+'；请刷新材料索取核查，勿连续重复发布。';}finally{busy.value=false;}if(!error.value)await load();}
async function accept(row:components['schemas']['AdmissionMaterialRequest']){try{await ElMessageBox.confirm('确认已检查供应商提交的材料？采纳将替换索取项对应的申请文件，其他材料保留。之后仍须提交准入审核。','采纳准入材料',{type:'warning'});}catch{return;}if(disposed)return;busy.value=true;error.value='';try{const result=await session.client.POST('/admission-material-requests/{id}/accept',{params:{path:{id:row.id}},body:{version:row.version},signal:abort.signal});if(!result.data)throw new Error(result.error?.error.message??'采纳未成功，请刷新核查');emit('changed');}catch(e){error.value=e instanceof Error?e.message:'采纳结果未知，请刷新核查';}finally{busy.value=false;}if(!error.value)await load();}
async function cancel(row:components['schemas']['AdmissionMaterialRequest']){let reason='';try{const result=await ElMessageBox.prompt('请填写供应商可见的撤销说明（最多500字）','撤销材料索取',{inputPattern:/\S/,inputErrorMessage:'说明不能为空',inputValidator:value=>value.length<=500||'最多500字'});reason=result.value;}catch{return;}if(disposed)return;busy.value=true;error.value='';try{const result=await session.client.POST('/admission-material-requests/{id}/cancel',{params:{path:{id:row.id}},body:{version:row.version,reason},signal:abort.signal});if(!result.data)throw new Error(result.error?.error.message??'撤销未成功，请刷新核查');}catch(e){error.value=e instanceof Error?e.message:'结果未知，请刷新核查';}finally{busy.value=false;}if(!error.value)await load();}
async function download(row:components['schemas']['AdmissionMaterialRequest'],type:string,name:string){busy.value=true;error.value='';try{const result=await session.client.GET('/admission-material-requests/{id}/materials/{type}/content',{params:{path:{id:row.id,type}},parseAs:'blob',signal:abort.signal});if(disposed)return;if(!result.data)throw new Error('文件不可用或无下载权限');const url=URL.createObjectURL(result.data);try{const link=document.createElement('a');link.href=url;link.download=name;link.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(e){error.value=e instanceof Error?e.message:'下载失败';}finally{busy.value=false;}}
</script>
<template><section class="admission-portal" :aria-busy="busy"><h3>供应商准入材料协作</h3><p>仅明确发布的材料名称和对外说明会进入门户；上传、采纳与准入审核相互独立。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-button :loading="busy" @click="load">刷新材料索取</el-button><p v-if="opened&&!rows.length">尚未向供应商发布材料索取。</p>
 <el-form v-if="canManage&&['DRAFT','REVISION_REQUIRED'].includes(application.status)&&!rows.some(row=>['OPEN','SUBMITTED'].includes(row.state))" label-position="top" @submit.prevent="publish"><el-form-item label="选择向供应商索取的材料（最多5项，所选名称将公开）"><el-checkbox-group v-model="types" :disabled="busy"><el-checkbox v-for="item in application.materials" :key="item.type" :value="item.type">{{item.name}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="供应商可见说明"><el-input v-model="instruction" type="textarea" :rows="3" maxlength="1000" show-word-limit :disabled="busy"/></el-form-item><el-button type="primary" :disabled="busy" @click="publish">发布准入材料索取</el-button></el-form>
 <article v-for="row in rows" :key="row.id"><h4>{{names[row.state]}} · {{row.applicationNo}}</h4><p class="instruction">{{row.instruction}}</p><p v-if="row.closeNote" class="instruction">撤销说明：{{row.closeNote}}</p><ul><li v-for="item in row.items" :key="item.type">{{item.name}}<template v-if="item.fileName"> · {{item.fileName}} <el-button link :disabled="busy||!canDownload" @click="download(row,item.type,item.fileName)">下载索取材料</el-button></template></li></ul><template v-if="canManage"><el-button v-if="row.state==='SUBMITTED'" type="primary" :disabled="busy" @click="accept(row)">核对并采纳材料</el-button><el-button v-if="['OPEN','SUBMITTED'].includes(row.state)" :disabled="busy" @click="cancel(row)">撤销此材料索取</el-button></template></article>
</section></template>
<style scoped>.admission-portal{margin-top:20px;min-width:0;overflow-wrap:anywhere}.instruction{white-space:pre-wrap;overflow-wrap:anywhere}article{padding:12px 0;border-bottom:1px solid var(--el-border-color)}.el-checkbox-group{display:flex;flex-wrap:wrap;gap:8px}:deep(.el-checkbox){height:auto;white-space:normal;max-width:100%}:deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere}</style>
